python3 << 'EOF'
import pdfplumber
import openpyxl
import json

# Extract all data from PDF
pdf_data = {}
with pdfplumber.open('/root/employees_backup.pdf') as pdf:
    for page in pdf.pages:
        tables = page.extract_tables()
        if tables:
            for table in tables:
                for row_num, row in enumerate(table):
                    if row_num == 0:  # Skip header
                        continue
                    if row[0] and row[0].startswith('EMP'):
                        emp_id = row[0]
                        try:
                            salary = int(row[5].replace(',', ''))
                        except:
                            salary = row[5]
                        try:
                            years = int(row[6])
                        except:
                            years = row[6]
                        try:
                            score = float(row[8])
                        except:
                            score = row[8]

                        pdf_data[emp_id] = {
                            'first': row[1],
                            'last': row[2],
                            'dept': row[3],
                            'position': row[4],
                            'salary': salary,
                            'years': years,
                            'location': row[7],
                            'score': score
                        }

# Extract all data from Excel
excel_data = {}
wb = openpyxl.load_workbook('/root/employees_current.xlsx')
ws = wb.active
for row_num, row in enumerate(ws.iter_rows(values_only=True), 1):
    if row_num == 1:  # Skip header
        continue
    if row[0] and str(row[0]).startswith('EMP'):
        emp_id = str(row[0])
        try:
            salary = int(row[5]) if row[5] else None
        except:
            salary = row[5]
        try:
            years = int(row[6]) if row[6] else None
        except:
            years = row[6]
        try:
            score = float(row[8]) if row[8] else None
        except:
            score = row[8]

        excel_data[emp_id] = {
            'first': row[1],
            'last': row[2],
            'dept': row[3],
            'position': row[4],
            'salary': salary,
            'years': years,
            'location': row[7],
            'score': score
        }

# Find deleted employees (in PDF but not in Excel)
deleted_employees = sorted([emp_id for emp_id in pdf_data if emp_id not in excel_data])

# Find modified employees
modified_employees = []
field_mapping = {
    'first': 'First',
    'last': 'Last',
    'dept': 'Dept',
    'position': 'Position',
    'salary': 'Salary',
    'years': 'Years',
    'location': 'Location',
    'score': 'Score'
}

for emp_id in sorted(excel_data.keys()):
    if emp_id in pdf_data:
        pdf_record = pdf_data[emp_id]
        excel_record = excel_data[emp_id]

        for field, display_name in field_mapping.items():
            pdf_val = pdf_record.get(field)
            excel_val = excel_record.get(field)

            if pdf_val != excel_val:
                modified_employees.append({
                    'id': emp_id,
                    'field': display_name,
                    'old_value': pdf_val,
                    'new_value': excel_val
                })

# Create result
result = {
    'deleted_employees': deleted_employees,
    'modified_employees': modified_employees
}

# Write to file
with open('/root/diff_report.json', 'w') as f:
    json.dump(result, f, indent=2)

print(f"Report generated successfully!")
print(f"Deleted employees: {len(deleted_employees)}")
print(f"Modified records: {len(modified_employees)}")
print(f"\nFirst 10 deleted:")
for emp_id in deleted_employees[:10]:
    print(f"  {emp_id}")
print(f"\nFirst 10 modified:")
for record in modified_employees[:10]:
    print(f"  {record}")
EOF

